function run(medicoSelecionadoRaw, listaMedicosJson) {
    var result = {
        acaoSeguinte: "PEDIR_CPF",
        nextPage: "1",
        doctorId: "",
        doctorName: "",
        isInternal: "false",
        externalLink: "",
        externalPhone: "",
        queueName: "Recepção Central / Suporte"
    };
    try {
        var rawText = "";
        if (typeof medicoSelecionadoRaw === "string") {
            var trimmed = medicoSelecionadoRaw.trim();
            if (trimmed.indexOf("{") === 0) {
                try {
                    var parsed = JSON.parse(trimmed);
                    if (parsed.list_reply) {
                        rawText = parsed.list_reply.title || parsed.list_reply.id || "";
                    } else if (parsed.text) {
                        rawText = parsed.text;
                    } else {
                        rawText = trimmed;
                    }
                } catch(e) {
                    rawText = trimmed;
                }
            } else {
                rawText = trimmed;
            }
        } else if (medicoSelecionadoRaw && typeof medicoSelecionadoRaw === "object") {
            if (medicoSelecionadoRaw.list_reply) {
                rawText = medicoSelecionadoRaw.list_reply.title || medicoSelecionadoRaw.list_reply.id || "";
            } else if (medicoSelecionadoRaw.text) {
                rawText = medicoSelecionadoRaw.text;
            } else {
                rawText = JSON.stringify(medicoSelecionadoRaw);
            }
        } else {
            rawText = (medicoSelecionadoRaw || "").toString().trim();
        }

        var doctors = [];
        try {
            doctors = JSON.parse(listaMedicosJson || "[]");
        } catch(e) {
            doctors = [];
        }

        var selectedDoc = null;

        // 1. Checa se o usuário digitou o número da opção (ex: "1", "2", "3", "4", "1.", "2 -")
        var numMatch = rawText.match(/^(\d+)/);
        if (numMatch) {
            var idx = parseInt(numMatch[1], 10) - 1;
            if (idx >= 0 && idx < doctors.length) {
                selectedDoc = doctors[idx];
            }
        }

        // 2. Se não achou por número, busca por correspondência de texto (nome do médico ou especialidade)
        if (!selectedDoc && doctors.length > 0 && rawText.length > 0) {
            var searchTerms = rawText.toLowerCase().replace(/[^a-z0-9 ]/g, " ").split(/\s+/);
            var bestScore = 0;

            for (var i = 0; i < doctors.length; i++) {
                var d = doctors[i];
                var dName = (d.doctorName || d.name || "").toLowerCase();
                var dSpec = (d.specialty || d.description || "").toLowerCase();
                var combined = dName + " " + dSpec;

                var score = 0;
                for (var t = 0; t < searchTerms.length; t++) {
                    var term = searchTerms[t];
                    if (term.length > 1 && combined.indexOf(term) !== -1) {
                        score += 1;
                    }
                }

                if (score > bestScore) {
                    bestScore = score;
                    selectedDoc = d;
                }
            }
        }

        if (selectedDoc) {
            result.doctorName = selectedDoc.doctorName || selectedDoc.name || selectedDoc.medico || rawText;
            result.doctorId = (selectedDoc.id || "").toString();
            result.isInternal = (selectedDoc.isInternal === true || selectedDoc.isInternal === "true" || selectedDoc.isInternal === "TRUE") ? "true" : "false";
            result.externalLink = selectedDoc.externalLink || selectedDoc.linkWa || "";
            result.externalPhone = selectedDoc.externalPhone || "";
            result.queueName = selectedDoc.queue || selectedDoc.queueName || selectedDoc.fila || "Recepção Central / Suporte";
        } else {
            result.doctorName = rawText;
        }
        result.acaoSeguinte = "PEDIR_CPF";
    } catch (e) {
        result.acaoSeguinte = "PEDIR_CPF";
    }
    return JSON.stringify(result);
}

