function run(userCpfRaw) {
    try {
        if (!userCpfRaw) return JSON.stringify({ cpfValido: "INVALID", cleanCpf: "" });
        var cleanCpf = userCpfRaw.toString().replace(/\D/g, "");
        if (cleanCpf.length !== 11) return JSON.stringify({ cpfValido: "INVALID", cleanCpf: "" });
        if (/^(\d)\1{10}$/.test(cleanCpf)) return JSON.stringify({ cpfValido: "INVALID", cleanCpf: "" });
        var sum = 0, remainder = 0;
        for (var i = 1; i <= 9; i++) sum += parseInt(cleanCpf.substring(i - 1, i), 10) * (11 - i);
        remainder = (sum * 10) % 11;
        if (remainder === 10 || remainder === 11) remainder = 0;
        if (remainder !== parseInt(cleanCpf.substring(9, 10), 10)) return JSON.stringify({ cpfValido: "INVALID", cleanCpf: "" });
        sum = 0;
        for (var j = 1; j <= 10; j++) sum += parseInt(cleanCpf.substring(j - 1, j), 10) * (12 - j);
        remainder = (sum * 10) % 11;
        if (remainder === 10 || remainder === 11) remainder = 0;
        if (remainder !== parseInt(cleanCpf.substring(10, 11), 10)) return JSON.stringify({ cpfValido: "INVALID", cleanCpf: "" });
        return JSON.stringify({ cpfValido: "VALID", cleanCpf: cleanCpf });
    } catch (e) {
        return JSON.stringify({ cpfValido: "INVALID", cleanCpf: "" });
    }
}

